package com.projexa.coaching.ai.controller;
import com.projexa.coaching.common.tenant.TenantContextHolder; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/ai") public class AIInsightsController {private final JdbcTemplate db;public AIInsightsController(JdbcTemplate db){this.db=db;}
@GetMapping("/student/{studentId}") @PreAuthorize("hasAnyAuthority('reports.read','dashboard.read')") public Map<String,Object> student(@PathVariable UUID studentId){UUID t=TenantContextHolder.getRequired();List<Map<String,Object>> lowAttendance=db.queryForList("select count(*) total from attendance_records where tenant_id=? and student_id=? and status='ABSENT'",t,studentId);List<Map<String,Object>> results=db.queryForList("select percentage from results where tenant_id=? and student_id=? and status='PUBLISHED' order by published_at desc limit 5",t,studentId);List<String> signals=new ArrayList<>();if(!lowAttendance.isEmpty()&&((Number)lowAttendance.get(0).get("total")).intValue()>=5)signals.add("Attendance intervention suggested");if(results.size()>=2&&((Number)results.get(0).get("percentage")).doubleValue()<((Number)results.get(1).get("percentage")).doubleValue())signals.add("Recent performance decline detected");return Map.of("signals",signals,"mode","RULE_BASED_AI_READY","disclaimer","Signals are decision support and require teacher/admin review");}
}
